def transform(g):
    h,w=len(g),len(g[0]); out=[row[:] for row in g]
    for i in range(h):
        pos=[j for j in range(w) if g[i][j]==5]
        for a,b in zip(pos,pos[1:]):
            for j in range(a+1,b): out[i][j]=3
    for j in range(w):
        pos=[i for i in range(h) if g[i][j]==5]
        for a,b in zip(pos,pos[1:]):
            for i in range(a+1,b): out[i][j]=3
    return out
